(function(){
"use strict";
const TU101_ID="tu101";
const TU101_TOKEN_HASH="14722ede8207d2738ea187881e9ef519ecccfbc763e1493b43db4da4bb31616d";
const TU101_GROUP="Group 2 (04)";
const TU101_VERSION="1.0";
let tu101UnlockTarget="ec214";
let tu101Tab="progress";

const TU101_LECTURES=[
 {id:"l1",n:1,theme:"Theme 1 — Understanding the Contemporary World",title:"Understanding Southeast Asia: Diversity, Identity, and Why ASEAN Matter",instructor:"Asst. Prof. Dr. Morragotwong Phumplab",focus:["Southeast Asia as a diverse but connected region","Indigenous society, animism, rice cultivation and settlement patterns","Indianization, Sinicization, Islamization and Western colonial legacies","Multi-ethnicity, language families, hybrid culture and cultural kinship","Shared culture, national claims and cultural conflict"]},
 {id:"l2",n:2,theme:"Theme 1 — Understanding the Contemporary World",title:"What is Globalization? Understanding the International System in an Era of Global Disruption",instructor:"Asst. Prof. Dr. Pongphisoot Busbarat",focus:["Meaning and historical waves of globalization","Post-Cold War liberal international order","Technology, policy choices and free-market ideology as globalization drivers","New global actors and challenges to nation-state sovereignty","Economic gains, inequality, populism, geopolitics and deglobalization"]},
 {id:"l3",n:3,theme:"Theme 1 — Understanding the Contemporary World",title:"ASEAN Between Giants: U.S., China, and the New Global Cold War",instructor:"Asst. Prof. Dr. Pongphisoot Busbarat",focus:["ASEAN in U.S.–China strategic competition","Risk, uncertainty and strategic positioning","Hedging as a Southeast Asian foreign-policy strategy","Why ASEAN states avoid simple binary alignment"]},
 {id:"l4",n:4,theme:"Theme 1 — Understanding the Contemporary World",title:"Global History: The Rise of Empires, States, and Nation-States",instructor:"Asst. Prof. Dr. Thep Boontanondha",focus:["Historical transition from empires to modern states","Nation-state formation and nationalism","National consciousness and imagined communities","Print, language, identity and political community"]},
 {id:"l5",n:5,theme:"Theme 2 — Southeast Asia in a Changing World",title:"Politics and Democratization in Southeast Asia",instructor:"Asst. Prof. Dr. Morragotwong Phumplab",focus:["Democratization and political change in Southeast Asia","Political families and dynasties","Geopolitics and non-traditional security pressures","How institutions, elites and family networks shape politics"]},
 {id:"l6",n:6,theme:"Theme 2 — Southeast Asia in a Changing World",title:"Politics and Religion in Southeast Asia",instructor:"Assoc. Prof. Chaiwat Meesanthan",focus:["Religious and political diversity across Southeast Asia","Religion as political legitimacy, governance and resistance","Colonialism, nationalism and post-independence nation-building","Country cases: Indonesia, Malaysia, Thailand, Philippines, Myanmar, Cambodia, Laos, Vietnam, Brunei and Timor-Leste","Religion, democracy, populism, minority rights and state control"]}
];

function e(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]))}
function tu101StateKey(){return activeUser?("d-study-tu101-state::"+activeUser.id):"d-study-tu101-state::anonymous"}
function freshTu101State(){return{version:TU101_VERSION,group:TU101_GROUP,status:Object.fromEntries(TU101_LECTURES.map(x=>[x.id,"Not Started"])),notes:{},quizHistory:[],updatedAt:new Date().toISOString()}}
function loadTu101State(){try{const x=JSON.parse(localStorage.getItem(tu101StateKey())||"null");return x&&typeof x==="object"?Object.assign(freshTu101State(),x):freshTu101State()}catch(_){return freshTu101State()}}
function saveTu101State(s){s.updatedAt=new Date().toISOString();localStorage.setItem(tu101StateKey(),JSON.stringify(s))}
function statusScore(s){return({"Not Started":0,"Learning":25,"Learned · Not Reviewed":50,"Reviewed & Practiced":75,"Mastered":100})[s]||0}
function tu101Progress(st){const vals=TU101_LECTURES.map(x=>statusScore(st.status[x.id]));return Math.round(vals.reduce((a,b)=>a+b,0)/vals.length)}

function ensureTu101Dom(){
  const grid=document.querySelector("#subjectScreen .subject-grid");
  if(grid&&!document.getElementById("subjectTu101Card")){
    const card=document.createElement("article");
    card.className="subject-card live tu101-card";card.id="subjectTu101Card";card.dataset.subject="tu101";
    card.innerHTML='<span class="subject-state" id="subjectTu101State">Locked</span><strong>TU101</strong><span>Thailand, ASEAN and the World</span><small>'+TU101_GROUP+' • Midterm workspace</small><div class="subject-card-actions"><button id="subjectTu101OpenBtn" type="button">Unlock TU101</button><button id="subjectTu101PreviewBtn" class="secondary" type="button">Preview</button></div>';
    const coming=grid.querySelector(".subject-card.coming");grid.insertBefore(card,coming||null);
  }
  if(!document.getElementById("tu101Shell")){
    const shell=document.createElement("div");shell.id="tu101Shell";shell.className="tu101-shell";shell.style.display="none";
    shell.innerHTML='<header><div class="wrap headerrow"><div><h1>D Study App • TU101</h1><div class="sub">Midterm • 80 MCQ • 40% • '+TU101_GROUP+'</div></div><div class="userbar"><button id="tu101BackBtn" class="secondary subject-back-btn" type="button">← Subjects</button><span id="tu101UserChip" class="userchip"></span><button id="tu101LogoutBtn" class="logout" type="button">Log out</button></div></div></header><main class="wrap"><nav class="tabs tu101-tabs" aria-label="TU101 navigation"><button class="tab active" data-tu101-tab="progress">📚 Progress</button><button class="tab" data-tu101-tab="summary">📝 Summary</button><button class="tab" data-tu101-tab="quiz">✅ Midterm</button><button class="tab" data-tu101-tab="notes">🗒️ Notes</button><button class="tab" data-tu101-tab="history">📈 History</button></nav><div id="tu101Workspace"></div></main><footer><b>D Study App v13.7</b> • TU101 subject workspace • separate local progress</footer>';
    document.body.appendChild(shell);
  }
  document.getElementById("subjectTu101OpenBtn")?.addEventListener("click",()=>chooseSubject("tu101"));
  document.getElementById("subjectTu101PreviewBtn")?.addEventListener("click",openTu101Preview);
  document.getElementById("tu101BackBtn")?.addEventListener("click",backToSubjects);
  document.getElementById("tu101LogoutBtn")?.addEventListener("click",()=>{document.getElementById("tu101Shell").style.display="none";logout()});
  document.querySelectorAll("[data-tu101-tab]").forEach(b=>b.addEventListener("click",()=>openTu101Tab(b.dataset.tu101Tab,true)));
}

function configureUnlockPanel(subjectId){
  tu101UnlockTarget=subjectId;
  const p=document.getElementById("subjectUnlockPanel");if(!p)return;
  const h=p.querySelector("h2"),desc=p.querySelector("p.small"),input=document.getElementById("subjectPasswordInput");
  if(subjectId==="tu101"){
    if(h)h.textContent="Enter the TU101 subject token";
    if(desc)desc.textContent="TU101 has a separate token and separate local study progress from EC214.";
    if(input)input.placeholder="TU101 token";
  }else{
    if(h)h.textContent="Enter the EC214 subject password";
    if(desc)desc.textContent="Enter it once for this local account. After successful redemption, the account keeps EC214 access; after a 24-hour active-subject session expires you only click Open EC214 again.";
    if(input)input.placeholder="Subject password";
  }
}
if(typeof DEPLOYED_SUBJECT_HASHES!=="undefined")DEPLOYED_SUBJECT_HASHES.tu101=TU101_TOKEN_HASH;

const coreRenderSubjectHub=renderSubjectHub;
renderSubjectHub=function(){
  coreRenderSubjectHub();
  ensureTu101Dom();
  if(!activeUser)return;
  const unlocked=hasSubjectAccess(activeUser,"tu101"),card=document.getElementById("subjectTu101Card"),stateEl=document.getElementById("subjectTu101State"),btn=document.getElementById("subjectTu101OpenBtn");
  card?.classList.toggle("unlocked",unlocked);
  if(stateEl)stateEl.textContent=unlocked?"Unlocked":"Locked";
  if(btn){btn.textContent=unlocked?"Open TU101":"Unlock TU101";btn.classList.toggle("secondary",unlocked)}
};

const coreChooseSubject=chooseSubject;
chooseSubject=function(subjectId){
  if(subjectId==="tu101"){
    configureUnlockPanel("tu101");
    if(hasSubjectAccess(activeUser,"tu101")){enterSubject("tu101");return}
    closeSubjectPreview();const p=document.getElementById("subjectUnlockPanel"),s=document.getElementById("subjectUnlockStatus"),input=document.getElementById("subjectPasswordInput");
    if(s)s.textContent="";if(p)p.hidden=false;setTimeout(()=>input?.focus(),0);return;
  }
  configureUnlockPanel("ec214");return coreChooseSubject(subjectId);
};

const coreOpenSubjectPreview=openSubjectPreview;
openSubjectPreview=function(subjectId){if(subjectId==="tu101")return openTu101Preview();configureUnlockPanel("ec214");return coreOpenSubjectPreview(subjectId)};

unlockSelectedSubject=async function(){
  const target=tu101UnlockTarget||"ec214",input=document.getElementById("subjectPasswordInput"),status=document.getElementById("subjectUnlockStatus"),value=input?input.value:"";
  const name=target==="tu101"?"TU101":"EC214";
  if(!value){if(status)status.textContent="Enter the "+name+" subject "+(target==="tu101"?"token.":"password.");return}
  if(await sha256Text(value)!==subjectPasswordHash(target)){if(status)status.textContent="Incorrect "+name+" subject "+(target==="tu101"?"token.":"password.");return}
  grantSubjectAccess(target);if(input)input.value="";if(status)status.textContent="";
  const panel=document.getElementById("subjectUnlockPanel");if(panel)panel.hidden=true;
  renderSubjectHub();enterSubject(target);
};
const unlockBtn=document.getElementById("subjectUnlockBtn");if(unlockBtn)unlockBtn.onclick=unlockSelectedSubject;

const coreEnterSubject=enterSubject;
enterSubject=function(subjectId,remember=true){
  if(subjectId!=="tu101")return coreEnterSubject(subjectId,remember);
  if(!hasSubjectAccess(activeUser,"tu101"))return;
  ensureTu101Dom();activeSubject="tu101";if(remember)rememberSubjectSession("tu101");
  document.getElementById("subjectScreen").style.display="none";document.getElementById("appShell").style.display="none";
  const shell=document.getElementById("tu101Shell");if(shell)shell.style.display="block";
  const chip=document.getElementById("tu101UserChip");if(chip)chip.textContent="👤 "+activeUser.username;
  const path=location.pathname.replace(/\/+$/,""),m=path.match(/\/tu101\/(progress|summary|quiz|notes|history)$/);
  tu101Tab=m?m[1]:"progress";openTu101Tab(tu101Tab,!m);
};

const coreBackToSubjects=backToSubjects;
backToSubjects=function(){
  if(activeSubject!=="tu101")return coreBackToSubjects();
  activeSubject=null;clearSubjectSession();const shell=document.getElementById("tu101Shell");if(shell)shell.style.display="none";renderSubjectHub();
};
const backBtn=document.getElementById("backToSubjectsBtn");if(backBtn)backBtn.onclick=backToSubjects;

function openTu101Tab(tab,push){
  tu101Tab=tab||"progress";document.querySelectorAll("[data-tu101-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tu101Tab===tu101Tab));
  if(push){const target=APP_BASE+"/tu101/"+tu101Tab+"/";if(location.pathname!==target)history.pushState({dStudy:true,subject:"tu101",tab:tu101Tab},"",target)}
  renderTu101();
}
function renderTu101(){
  const root=document.getElementById("tu101Workspace");if(!root||!activeUser)return;const st=loadTu101State();
  if(tu101Tab==="summary")root.innerHTML=tu101SummaryMarkup(st);
  else if(tu101Tab==="quiz")root.innerHTML=tu101QuizMarkup(st);
  else if(tu101Tab==="notes")root.innerHTML=tu101NotesMarkup(st);
  else if(tu101Tab==="history")root.innerHTML=tu101HistoryMarkup(st);
  else root.innerHTML=tu101ProgressMarkup(st);
  bindTu101(root,st);
}
function tu101ProgressMarkup(st){
  return '<div class="panel-intro"><div><div class="eyebrow">TU101 Midterm Dashboard</div><h2>'+e(TU101_GROUP)+'</h2><p>Separate TU101 progress. Nothing here changes EC214 notes, quiz history, or completion.</p></div></div>'+
  '<div class="tu101-hero card"><div><div class="eyebrow">Midterm Examination</div><h2>80 multiple-choice items • 40%</h2><p><b>Official course outline:</b> Lectures 1–6. Theme 1 covers Lectures 1–4; Theme 2 contributes only Lectures 5–6.</p><div class="tu101-tags"><span>Lecture 1–6</span><span>Theme 1: L1–L4</span><span>Theme 2: L5–L6</span><span>Group 2 (04)</span></div></div><div class="tu101-progress-big"><b>'+tu101Progress(st)+'%</b><span>lecture status</span></div></div>'+
  '<div class="tu101-scope-warning"><b>Scope check:</b> the official 2026 course outline lists <i>New Threats, New Challenges: Climate Change and Human Security in Southeast Asia</i> as <b>Lecture 7 / 18 Sep</b>, after Lectures 1–6, and explicitly says the Midterm covers Lectures 1–6. Your class message calling that topic “Week 6” is preserved privately. Until you confirm an instructor override, this workspace keeps Climate Change <b>outside</b> the official Midterm scope.</div>'+
  '<div class="tu101-lecture-grid">'+TU101_LECTURES.map(l=>'<article class="card tu101-lecture-card"><div class="eyebrow">'+e(l.theme)+'</div><h3>Lecture '+l.n+' — '+e(l.title)+'</h3><div class="small">'+e(l.instructor)+'</div><label class="tu101-status-label">Study status<select data-tu101-status="'+l.id+'">'+["Not Started","Learning","Learned · Not Reviewed","Reviewed & Practiced","Mastered"].map(x=>'<option '+(st.status[l.id]===x?'selected':'')+'>'+e(x)+'</option>').join("")+'</select></label><ul>'+l.focus.map(x=>'<li>'+e(x)+'</li>').join("")+'</ul></article>').join("")+'</div>';
}
function tu101SummaryMarkup(){
  return '<div class="panel-intro"><div><div class="eyebrow">Source-backed Lecture Map</div><h2>TU101 Midterm Summary Library</h2><p>This first TU101 deployment establishes the correct lecture scope and source map. Detailed lecture-by-lecture study summaries can now be built from the private source archive without mixing them into EC214.</p></div></div>'+
  '<div class="tu101-theme card"><h3>Theme 1 — Understanding the Contemporary World</h3><p>Lectures 1–4: regional diversity and identity → globalization and disruption → ASEAN amid U.S.–China competition → empires, states, nation-states and nationalism.</p></div>'+
  '<div class="tu101-theme card"><h3>Theme 2 — Southeast Asia in a Changing World</h3><p><b>Midterm scope only:</b> Lectures 5–6: politics/democratization and politics/religion in Southeast Asia.</p></div>'+
  TU101_LECTURES.map(l=>'<article class="card tu101-summary-card"><div class="eyebrow">'+e(l.theme)+'</div><h3>Lecture '+l.n+': '+e(l.title)+'</h3><div class="small">'+e(l.instructor)+'</div><h4>Current study map</h4><ul>'+l.focus.map(x=>'<li>'+e(x)+'</li>').join("")+'</ul><div class="exam-note"><b>Source status:</b> slide/readings are archived in the private TU101 source folder. This map is not pretending to be the final full summary yet.</div></article>').join("");
}
function tu101QuizMarkup(){
  return '<div class="panel-intro"><div><div class="eyebrow">Midterm Practice</div><h2>80-item exam blueprint</h2><p>The official exam format and scope are locked in before question generation.</p></div></div>'+
  '<div class="card tu101-exam-blueprint"><div class="tu101-blueprint-grid"><div><b>80</b><span>multiple-choice items</span></div><div><b>40%</b><span>course grade</span></div><div><b>6</b><span>lectures in official scope</span></div><div><b>2</b><span>themes represented</span></div></div><p><b>Planned practice structure:</b> lecture/topic parts + a full cumulative Midterm Mock, with question notes and confidence flags using TU101-only storage.</p><div class="tu101-pending">Question banks are intentionally not auto-generated from titles alone. The private Lecture 1–6 slides/readings are now archived so the next build can generate source-grounded questions.</div></div>';
}
function tu101NotesMarkup(st){
  return '<div class="panel-intro"><div><div class="eyebrow">TU101 Notes</div><h2>Lecture notes • '+e(TU101_GROUP)+'</h2><p>Saved under TU101-only keys. EC214 notes are untouched.</p></div></div>'+
  '<div class="tu101-notes-grid">'+TU101_LECTURES.map(l=>'<article class="card"><h3>Lecture '+l.n+' — '+e(l.title)+'</h3><textarea data-tu101-note="'+l.id+'" placeholder="What I do not understand, professor wording, exam trap, reading note…">'+e(st.notes[l.id]||"")+'</textarea></article>').join("")+'</div>';
}
function tu101HistoryMarkup(st){
  return '<div class="panel-intro"><div><div class="eyebrow">TU101 History</div><h2>Quiz History</h2><p>This history is separate from EC214.</p></div></div><div class="card">'+(st.quizHistory.length?st.quizHistory.map(x=>'<div>'+e(x)+'</div>').join(""):'No TU101 quiz attempts yet. The exam bank has not been generated.')+'</div>';
}
function bindTu101(root,st){
  root.querySelectorAll("[data-tu101-status]").forEach(sel=>sel.onchange=function(){st.status[sel.dataset.tu101Status]=sel.value;saveTu101State(st);renderTu101()});
  root.querySelectorAll("[data-tu101-note]").forEach(t=>t.oninput=function(){st.notes[t.dataset.tu101Note]=t.value;saveTu101State(st)});
}
function openTu101Preview(){
  ensureTu101Dom();const panel=document.getElementById("subjectPreviewPanel"),title=document.getElementById("subjectPreviewTitle"),body=document.getElementById("subjectPreviewBody");if(!panel||!body)return;
  tu101UnlockTarget="tu101";panel.hidden=false;document.getElementById("subjectUnlockPanel").hidden=true;if(title)title.textContent="TU101 Preview";
  body.innerHTML='<div class="tu101-preview card"><div class="eyebrow">TU101 • '+e(TU101_GROUP)+'</div><h2>Midterm workspace preview</h2><div class="tu101-blueprint-grid"><div><b>80</b><span>MCQ items</span></div><div><b>40%</b><span>of course grade</span></div><div><b>L1–L6</b><span>official scope</span></div><div><b>2 themes</b><span>Theme 1 + Theme 2 weeks 5–6</span></div></div><p>The subject will keep its own progress, notes, quiz drafts and history rather than sharing EC214 state.</p><button type="button" id="tu101PreviewUnlock">'+(hasSubjectAccess(activeUser,"tu101")?"Open TU101":"Unlock TU101")+'</button></div>';
  document.getElementById("tu101PreviewUnlock").onclick=()=>{panel.hidden=true;chooseSubject("tu101")};panel.scrollIntoView({behavior:"smooth",block:"start"});
}

window.addEventListener("popstate",function(){if(activeSubject==="tu101"){const m=location.pathname.replace(/\/+$/,"").match(/\/tu101\/(progress|summary|quiz|notes|history)$/);if(m){tu101Tab=m[1];renderTu101()}}});
window.addEventListener("storage",function(ev){if(activeUser&&ev.key===tu101StateKey()&&activeSubject==="tu101")renderTu101()});

ensureTu101Dom();
if(typeof APP_VERSION!=="undefined"){} 
const versionLabel=document.getElementById("appVersionLabel");if(versionLabel)versionLabel.textContent="D Study App v13.7";
document.querySelector(".subject-topbar .eyebrow")?.replaceChildren(document.createTextNode("D Study App • v13.7"));
renderSubjectHub();
if(activeUser){
  const s=getSubjectSession();
  if(s&&s.subjectId==="tu101"&&s.userId===activeUser.id&&s.expiresAt>Date.now()&&hasSubjectAccess(activeUser,"tu101"))enterSubject("tu101",false);
  else if(location.pathname.includes("/tu101/")&&hasSubjectAccess(activeUser,"tu101"))enterSubject("tu101",false);
}
})();